import httpx
from bs4 import BeautifulSoup
import json
import time
from datetime import datetime, date

headers = {
    'User-Agent': 'Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)'
}

def fetch_urls_from_sitemap(sitemap_url):
    try:
        resp = httpx.get(sitemap_url, headers=headers, timeout=15)
        if resp.status_code == 200:
            soup = BeautifulSoup(resp.text, 'xml')
            urls = []
            for url_elem in soup.find_all('url'):
                loc = url_elem.find('loc')
                lastmod = url_elem.find('lastmod')
                if loc:
                    urls.append({
                        'url': loc.text.strip(),
                        'lastmod': lastmod.text.strip() if lastmod else ''
                    })
            return urls
        else:
            print(f"  HTTP {resp.status_code} for {sitemap_url}")
    except Exception as e:
        print(f"  Error: {e}")
    return []

# Generate all dates from 2025-01-01 to 2025-05-31
start = date(2025, 1, 1)
end = date(2025, 5, 31)
all_urls = []
seen_urls = set()

def daterange(start, end):
    from datetime import timedelta
    for n in range(int((end - start).days) + 1):
        yield start + timedelta(n)

for dt in daterange(start, end):
    date_str = dt.strftime('%Y-%m-%d')
    sitemap_url = f'https://www.yidaiyilu.gov.cn/websitemap/article/{date_str}.xml'
    print(f"Fetching {date_str}...")
    urls = fetch_urls_from_sitemap(sitemap_url)
    for u in urls:
        if u['url'] not in seen_urls:
            seen_urls.add(u['url'])
            all_urls.append(u)
    time.sleep(0.3)  # delay to be polite

print(f"\nTotal unique articles: {len(all_urls)}")
with open('/tmp/all_articles.json', 'w') as f:
    json.dump(all_urls, f, indent=2)
print("Saved to /tmp/all_articles.json")
